--- 显示器选择器：名称（字符串）、ID（整数）或 HL.Monitor 对象
---@alias HL.MonitorSelector string|integer|HL.Monitor
--- 工作区选择器：名称/ID（字符串或整数）或 HL.Workspace 对象
---@alias HL.WorkspaceSelector string|integer|HL.Workspace
--- 窗口选择器：地址/类名（字符串）、ID（整数）或 HL.Window 对象
---@alias HL.WindowSelector string|integer|HL.Window
--- 二维向量：HL.Vec2 对象、{x=,y=} 表、{x, y} 数组或 "x,y" 字符串
---@alias HL.Vec2Like HL.Vec2|{x:number, y:number}|{[1]:number, [2]:number}|string
--- CSS 间距：整数，或 {top?, right?, bottom?, left?} 表
---@alias HL.CssGap integer|{top?:integer, right?:integer, bottom?:integer, left?:integer}
--- 渐变：颜色字符串，或 {colors=string[], angle?=number} 表
---@alias HL.Gradient string|{colors:string[], angle?:number}

--- 派发器描述：由 hl.dsp.* 构造，传给 hl.bind() 作为按键动作
---@class HL.Dispatcher
local __HL_Dispatcher = {}

--- 二维向量（坐标）
---@class HL.Vec2
---@field x number -- X 坐标
---@field y number -- Y 坐标
local __HL_Vec2 = {}

--- 矩形区域（布局用）
---@class HL.Box
---@field x number -- 左上角 X
---@field y number -- 左上角 Y
---@field w number -- 宽度
---@field h number -- 高度
local __HL_Box = {}

--- 布局目标：布局算法为每个窗口分配的目标区域
---@class HL.LayoutTarget
---@field index integer -- 目标序号
---@field window HL.Window|nil -- 对应窗口（可能为空，如占位目标）
---@field box HL.Box -- 当前分配的区域
---@field place fun(self: HL.LayoutTarget, box: HL.Box): nil -- 将窗口放置到指定区域
---@field set_box fun(self: HL.LayoutTarget, box: HL.Box): nil -- 直接设置区域
local __HL_LayoutTarget = {}

--- 布局上下文：自定义布局（hyprland layout）的输入
---@class HL.LayoutContext
---@field area HL.Box -- 可用区域
---@field targets HL.LayoutTarget[] -- 全部布局目标
---@field grid_cell fun(self: HL.LayoutContext, i: integer, cols: integer, rows?: integer): HL.Box -- 网格布局：第 i 格，共 cols 列（rows 可选）
---@field column fun(self: HL.LayoutContext, i: integer, n: integer): HL.Box -- 列布局：第 i 列，共 n 列
---@field row fun(self: HL.LayoutContext, i: integer, n: integer): HL.Box -- 行布局：第 i 行，共 n 行
---@field split fun(self: HL.LayoutContext, box: HL.Box, side: 'left'|'right'|'top'|'bottom'|'up'|'down', ratio: number): HL.Box -- 按比例分割区域（side: left/right/top/bottom/up/down）
local __HL_LayoutContext = {}

--- 布局提供者：hl.layout.register() 注册的自定义布局接口
---@class HL.LayoutProvider
---@field recalculate fun(ctx: HL.LayoutContext): nil -- 重新计算布局
---@field layout_msg? fun(ctx: HL.LayoutContext, msg: string): boolean|string|nil -- 处理布局消息（返回 true 表示已消费）
local __HL_LayoutProvider = {}

--- 按键绑定选项（hl.bind() 的第三个参数）
---@class HL.BindOptions
---@field repeating? boolean -- 按住时重复触发
---@field locked? boolean -- 锁屏或输入被捕获时仍生效
---@field release? boolean -- 在释放而非按下时触发
---@field non_consuming? boolean -- 不吞掉按键（其他程序仍可收到）
---@field transparent? boolean -- 透传：不执行动作，仅用于 submap 内覆盖
---@field ignore_mods? boolean -- 忽略修饰键状态（如 CapsLock 开关）
---@field dont_inhibit? boolean -- 不抑制 idle 抑制
---@field long_press? boolean -- 长按触发
---@field submap_universal? boolean -- 在所有 submap 中均生效
---@field click? boolean -- 点击触发
---@field drag? boolean -- 拖拽触发
---@field description? string -- 绑定描述（供 cheatsheet/键位菜单显示）
---@field desc? string -- 描述别名
---@field device? {inclusive?: boolean, list?: string[]} -- 仅对指定设备生效：inclusive=false 时排除 list 中的设备
---@field allow_input_capture? boolean -- 允许捕获输入
local __HL_BindOptions = {}

--- 定时器选项（hl.timer() 的参数）
---@class HL.TimerOptions
---@field timeout integer -- 超时时间（毫秒）
---@field type "repeat"|"oneshot" -- repeat=重复触发；oneshot=仅触发一次
local __HL_TimerOptions = {}

--- 触控板手势定义（hl.gesture() 的参数）
---@class HL.GestureSpec
---@field fingers integer -- 手指数量
---@field direction string -- 手势方向（u/d/l/r，可组合 f/b）
---@field action string|function -- 手势动作：dispatcher 或函数
---@field mods? string -- 修饰键（如 "SUPER"）
---@field scale? number -- 相对距离缩放
---@field mode? string -- 模式（如 "workspace"）
---@field zoom_level? number -- 缩放级别（水平手势）
---@field workspace_name? string -- 目标工作区
---@field disable_inhibit? boolean -- 禁用抑制
local __HL_GestureSpec = {}

