--- 输入设备配置（hl.device() 的参数，name 必填）
---@class HL.DeviceSpec
---@field absolute_region_position? boolean -- 使用绝对区域位置
---@field accel_profile? string -- 加速曲线（"adaptive"/"flat"）
---@field active_area_position? HL.Vec2Like -- 活动区域位置
---@field active_area_size? HL.Vec2Like -- 活动区域大小
---@field clickfinger_behavior? boolean -- 触摸板：点击手指行为
---@field disable_while_typing? boolean -- 打字时禁用
---@field drag_3fg? integer|boolean -- 三指拖拽
---@field drag_lock? integer|boolean -- 拖拽锁定
---@field enabled? boolean -- 是否启用设备
---@field flip_x? boolean -- 翻转 X
---@field flip_y? boolean -- 翻转 Y
---@field kb_file? string -- 键盘：自定义键位映射文件
---@field kb_layout? string -- 键盘布局（如 "us"）
---@field kb_model? string -- 键盘型号
---@field kb_options? string -- 键盘选项
---@field kb_rules? string -- 键盘规则
---@field kb_variant? string -- 键盘变体
---@field keybinds? boolean -- 是否启用按键绑定
---@field left_handed? boolean -- 左手模式（鼠标）
---@field middle_button_emulation? boolean -- 中键模拟
